	cps iz, 0
	jrl lt, FloppyCtrl_LoadIzAndContinue
	lds wa, 1
	calr NoteEventBuffer_Store
	calr NoteEvent_LoadSoundGenParams
	ldda32 xwa, 3186
	ld xbc, (xsp + 74)
	ld_sril XIX, (xsp + 0x0406)
	call (xix)
	ld_sril XHL, (xsp + 0x0402)
	call (xhl)
	ld iz, hl
	cps iz, 0
	jrl lt, FloppyCtrl_LoadIzAndContinue
	lds wa, 2
	calr NoteEventBuffer_Store
	calr NoteEvent_LoadSoundGenParams
	ldda32 xwa, 3186
	ld xbc, (xsp + 78)
	ld_sril XIX, (xsp + 0x0406)
	call (xix)
	ld_sril XHL, (xsp + 0x0402)
	call (xhl)
	ld iz, hl
	cps iz, 0
	jrl lt, FloppyCtrl_LoadIzAndContinue
	lds wa, 3
	calr NoteEventBuffer_Store
	calr NoteEvent_LoadSoundGenParams
	ldda32 xwa, 3186
	ld xbc, (xsp + 82)
	ld_sril XIX, (xsp + 0x0406)
	call (xix)
	ld_sril XHL, (xsp + 0x0402)
	call (xhl)
	ld iz, hl
	cps iz, 0
	jrl lt, FloppyCtrl_LoadIzAndContinue
	lds wa, 4
	calr NoteEventBuffer_Store
	calr NoteEvent_LoadSoundGenParams
	ldda32 xwa, 3186
	ld xbc, (xsp + 86)
	ld_sril XIX, (xsp + 0x0406)
	call (xix)
	ld_sril XHL, (xsp + 0x0402)
	call (xhl)
	ld iz, hl
	cps iz, 0
	jrl lt, FloppyCtrl_LoadIzAndContinue
	lds wa, 5
	calr NoteEventBuffer_Store
	calr NoteEvent_LoadSoundGenParams
	ldda32 xwa, 3186
	ld xbc, (xsp + 90)
	ld_sril XIX, (xsp + 0x0406)
	call (xix)
	ld_sril XHL, (xsp + 0x0402)
	call (xhl)
	ld iz, hl
	cps iz, 0
	jr lt, FloppyCtrl_LoadIzAndContinue
	lds wa, 6
	calr NoteEventBuffer_Store
	calr NoteEvent_LoadSoundGenParams
	ldda32 xwa, 3186
	ld xbc, (xsp + 94)
