	call TmFlash_CopyToExtMem

FloppyCtrl_LoadIzAndContinue:
	ld hl, iz
	jr LABEL_F18BF8

Floppy_SetHLFF9A_RetZero:
	ldw hl, 0xFF9A

LABEL_F18BF8:
	popw iz
	st_dri3b L, 0xFD, 0x08, 0x04
	ret

