	ld xiz, xwa
	ld_sril XIX, (xsp + 0x0418)
	call (xix)
	cp xhl, xiz
	jr ge, FloppyDisk_CopyNoteBuffers
	ldw hl, 0xFF9B
	jrl FloppyCtrl_PopIzStoreRet

